Table({
  source: warehouses(),
  columns: [
    { id: "name", label: "Name" },
    { id: "status", label: "Status" },
  ],
  rowActions: [
    {
      label: "Suspend",
      action: suspendWarehouse,
      input: { warehouse: "name" },
      when: { field: "status", equals: "RUNNING" },
    },
  ],
  searchable: true,
})
